        console.error('[ChatProfileSelector] Error loading profiles:', error)
        this.profiles = []
      }
    },
    onProfilesSelected(selectedItems) {
      this.$emit('update:selected-profiles', selectedItems)
      this.$emit('profiles-changed', selectedItems)
    }
  }
}
